<?php require_once __DIR__.'/../includes/student_auth_check.php';require_once __DIR__.'/../config/db.php';$classes=$recent=$notes=[];try{$p=db();$q=$p->prepare("SELECT b.*,s.name subject,u.full_name tutor FROM bookings b JOIN subjects s ON s.id=b.subject_id JOIN tutors t ON t.id=b.tutor_id JOIN users u ON u.id=t.user_id WHERE b.student_id=? AND b.booking_date>=CURDATE() ORDER BY b.booking_date LIMIT 3");$q->execute([$_SESSION['user_id']]);$classes=$q->fetchAll();$q=$p->prepare('SELECT * FROM notifications WHERE user_id=? AND is_read=0 ORDER BY created_at DESC LIMIT 5');$q->execute([$_SESSION['user_id']]);$notes=$q->fetchAll();}catch(Throwable $e){}$pageTitle='Student dashboard';require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/navbar.php';?><main class="section-soft py-5"><div class="container"><h1 class="h2">Welcome, <?=e($_SESSION['user_name'])?></h1><div class="row g-4 mt-1"><div class="col-lg-8"><div class="profile-section"><h2 class="h5">Upcoming classes</h2><?php foreach($classes as $x):?><div class="border-top py-2"><strong><?=e($x['subject'])?></strong> with <?=e($x['tutor'])?><br><small><?=e($x['booking_date'])?> · <?=date('g:i A',strtotime($x['start_time']))?></small></div><?php endforeach;if(!$classes):?><p class="text-secondary">No upcoming classes.</p><?php endif;?></div></div><div class="col-lg-4"><div class="profile-section"><h2 class="h5">Quick links</h2><a class="btn btn-brand w-100 mb-2" href="../find-tutor.php">Find tutors</a><a class="btn btn-outline-brand w-100" href="../schedule.php">My schedule</a></div></div></div><div class="profile-section mt-4"><h2 class="h5">Notifications</h2><?php foreach($notes as $n):?><div class="border-top py-2"><?=e($n['message'])?></div><?php endforeach;if(!$notes):?><p class="text-secondary mb-0">You are all caught up.</p><?php endif;?></div></div></main><?php require __DIR__.'/../includes/footer.php';?>
